INSERT INTO "bills" VALUES(10,'258','Poselski projekt ustawy o rekompensatach za szkody wyrządzone przez ptaki','2026-09-04T14:41:22',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"258","title":"Poselski projekt ustawy o rekompensatach za szkody wyrządzone przez ptaki","description":"projekt dotyczy umożliwienia wypłaty rekompensat ze środków budżetu państwa, za szkody wyrządzone przez ptaki roślinożerne w uprawach na gruntach ornych oraz kormorana na gruntach pod stawami rybnymi","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-01-22","document_date":"2024-01-22","change_date":"2026-09-04T14:41:22","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["1387"]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'316','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-09-07T11:39:30',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"316","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania korzystania przez osoby z niepełnosprawnościami z usługi asystencji osobistej i stworzenia w ten sposób trwałych warunków dla osób z niepełnosprawnościami do realizacji możliwie pełnego samodzielnego życia","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-03-04","document_date":"2024-03-04","change_date":"2026-09-07T11:39:30","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["1929","1933"]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:56:24+00:00');
INSERT INTO "bills" VALUES(10,'1387','Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw','2026-09-04T14:41:22',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"1387","title":"Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw","description":"projekt dotyczy m. in. dodania do katalogu gatunków m. in. kormorana czarnego, żurawia, dzikich gęsi z rodzaju Anser, łabędzi, kruka i czapli siwej, za których szkody przysługuje rekompensata, określenia podmiotu odpowiedzialnego za szacowanie i wypłatę odszkodowań (dyrektor oddziału terenowego Krajowego Ośrodka Wsparcia rolnictwa), zapewnienia udziału izb rolniczych oraz jednostek doradztwa rolniczego w procesie potwierdzania i dokumentowania szkód wyrządzonych przez ptaki","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-06-03","document_date":"2025-06-03","change_date":"2026-09-04T14:41:22","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["258"]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
