INSERT INTO "bills" VALUES(10,'1962','Komisyjny projekt ustawy o zmianie ustawy - Prawo o adwokaturze','2026-09-04T12:52:14','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"1962","title":"Komisyjny projekt ustawy o zmianie ustawy - Prawo o adwokaturze","description":"projekt dotyczy zmian w zakresie finansowania działalności samorządu adwokackiego i gospodarki finansowej jego organów, zadań samorządu i kompetencji jego organów, obowiązków adwokatów i aplikantów adwokackich dotyczących świadczenia pomocy prawnej, obowiązków adwokatów związanych z członkostwem w samorządzie i ich odpowiedzialności dyscyplinarnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-17","document_date":"2025-10-16","change_date":"2026-09-04T12:52:14","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2271','Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka','2026-09-04T12:46:31','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2271","title":"Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka","description":"projekt dotyczy ustanowienia zasad i trybu wykonywania orzeczeń Europejskiego Trybunału Praw Człowieka, wydanych w sprawach ze skarg indywidualnych, w których stroną jest Rzeczpospolita Polska, w tym sposobu koordynacji współdziałania podmiotów publicznych w celu wykonania orzeczeń Trybunału.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-13","document_date":"2026-02-13","change_date":"2026-09-04T12:46:31","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2363','Poselski projekt ustawy o rynku kryptoaktywów','2026-09-07T12:38:20','2026-09-04',0,'skipped_prefilter','[]','{"term":10,"number":"2363","title":"Poselski projekt ustawy o rynku kryptoaktywów","description":"projekt dotyczy wprowadzenia rozwiązań w obszarze sektora rynku kryptoaktywów, mających na celu zapewnienie stosowania rozporządzenia PE i Rady (UE) 2023/1114, w szczególności w zakresie skutecznego nadzoru i ochrony inwestorów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-09","document_date":"2025-12-08","change_date":"2026-09-07T12:38:20","closure_date":"2026-09-04","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["2528","2529","2530"]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:56:24+00:00');
INSERT INTO "bills" VALUES(10,'2394','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw','2026-09-01T19:34:40',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2394","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw","description":"projekt dotyczy określenia inwestycji o strategicznym znaczeniu dla rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej w rozumieniu ustawy z dnia 20 grudnia 1996 r. o portach i przystaniach morskich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-21","document_date":"2025-10-17","change_date":"2026-09-01T19:34:40","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2410','Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw','2026-08-27T11:15:41','2026-07-03',1,'skipped_prefilter','[]','{"term":10,"number":"2410","title":"Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw","description":"projekt dotyczy doprecyzowania, które przepisy Prawa budowlanego mają zastosowanie, gdy pozwolenie na budowę dotyczy tylko części obiektu jądrowego lub etapu inwestycji, wprowadzenia nowej kategorii decyzji - pozwolenie na budowę dotyczące wstępnych robót budowlanych przy obiekcie jądrowym.\nProjekt umożliwia podział inwestycji jądrowej na etapy, także dla części obiektów, które nie mogą samodzielnie funkcjonować; wprowadzenie wymogu \nposiadania zgody Prezesa Państwowej Agencji Atomistyki na roboty budowlane, które mają znaczenie dla bezpieczeństwa jądrowego i ochrony radiologicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-31","document_date":"2026-03-30","change_date":"2026-08-27T11:15:41","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2411','Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną','2026-09-04T12:52:43','2026-09-04',1,'analyzed','["straz_graniczna"]','{"term":10,"number":"2411","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną","description":"projekt dotyczy wzmocnienia kontroli sądów nad działaniami służb stosujących tzw. kontrolę operacyjną. Chodzi o niejawne działania, np. podsłuchy czy obserwację, które są wykorzystywane do zapobiegania i wykrywania przestępstw. Zmiany wzmocnią ochronę praw obywateli - zwłaszcza prawa do prywatności - oraz zwiększą przejrzystość działań służb. Nowe przepisy będą dotyczyć m.in. służb specjalnych, Policji oraz Straży Granicznej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-01","document_date":"2026-04-01","change_date":"2026-09-04T12:52:43","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-04-01", "print_number": "2411", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SPC", "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "KSS", "re