file": null, "text_after3": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-07-29", "print_number": "2820-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/2820-A/2820-A.pdf", "text_after3": null, "children": []}]}, {"stage_name": "III czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-07-31", "print_number": null, "sitting_num": 63, "decision": "uchwalono", "committee_code": null, "report_file": null, "text_after3": "https://api.sejm.gov.pl/sejm/term10/processes/2411/attachment/2411_u3.pdf", "children": [{"stage_name": "Głosowanie", "stage_type": "Voting", "date": "2026-07-31", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]}, {"stage_name": "Stanowisko Senatu", "stage_type": "SenatePosition", "date": "2026-08-06", "print_number": "2991", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-07", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SPC", "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-07", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "children": []}]}, {"stage_name": "Praca w komisjach nad stanowiskiem Senatu", "stage_type": "CommitteeWork", "date": "2026-09-02", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-09-02", "print_number": "3023", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3023/3023.pdf", "text_after3": null, "children": []}]}, {"stage_name": "Rozpatrywanie na forum Sejmu stanowiska Senatu", "stage_type": "SenatePositionConsideration", "date": "2026-09-04", "print_number": null, "sitting_num": 64, "decision": "przyjęto część poprawek", "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Uchwalono", "stage_type": "End", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]','13d4a59a4e62c4dbc2ca3856f740c618429f81ee80f5908d7c2a33db9425aaa8','{"analysis":{"relevant":false,"score":1,"category":"marginal","summary":"Правительственный проект усиливает судебный контроль за так называемым «kontrola operacyjna» (оперативный контроль — скрытая прослушка, наблюдение), который применяют Полиция, Straż Graniczna (Пограничная служба), ABW, CBA, SKW, KAS, Żandarmeria Wojskowa и SOP. Суды будут обязаны обосновывать каждое постановление о назначении или продлении такого контроля, получать информацию о его результатах и ходе, а также смогут в любой момент прекратить контроль. Вводятся сроки уничтожения материалов (3 месяца с возможным продлением на 3 месяца) и обязанность информировать суд об их уничтожении. Инспектор внутреннего надзора (INW) лишается права применять оперативный контроль и «контролируемую закупку». Проект не касается пребывания, работы или социальных прав иностранцев — он относится к процедурам спецслужб и защите приватности всех лиц на территории Польши.","key_changes":["Обязанность суда обосновывать постановления о назначении и продлении оперативного контроля","Суд и прокурор получают право в любой момент постановить о прекращении оперативного контроля","Службы обязаны информировать суд о результатах и, по требованию, о ходе контроля","Материалы, непригодные для уголовного процесса, уничтожаются в течение 3 месяцев (+3 месяца в особых случаях) с уведомлением суда","Отмена права Инспектора внутреннего надзора на оперативный контроль и контролируемую закупку","Ежегодный отчёт МВД Сейму и Сенату о деятельности Straż Graniczna в этой сфере (первый — до 30 июня 2027 г.)"],"affected_groups":["Все лица на территории Польши, включая иностранцев, в отношении которых применяется оперативный контроль","Сотрудники служб и судов"],"practical_impact":"Для иностранца в повседневной жизни ничего не меняется: документы, сроки и разрешения на пребывание не затрагиваются. Косвенно усиливаются гарантии приватности при скрытых мероприятиях служб, в том числе Пограничной службы.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.9,"rationale":"Проект регулирует процедуры судебного надзора над спецслужбами и не изменяет правил пребывания, работы или социальных прав иностранцев, поэтому значение для них минимальное.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v1","input_chars":64556,"truncated":false,"text_source":"pdf","created_at":"2026-09-07T13:52:39Z","input_tokens":33683,"output_tokens":987,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2411/2411.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
