INSERT INTO "bills" VALUES(10,'2530','Poselski projekt ustawy o kryptoaktywach','2026-09-07T12:38:20','2026-09-04',0,'skipped_prefilter','[]','{"term":10,"number":"2530","title":"Poselski projekt ustawy o kryptoaktywach","description":"projekt dotyczy zapewnienia stosowania na terytorium RP rozporządzenia PE i Rady (UE) 2023/1114 z dnia 31 maja 2023 r. w sprawie rynków kryptoaktywów oraz zmiany rozporządzeń (UE) nr 1093/2010 i (UE) nr 1095/2010 oraz dyrektyw 2013/36/UE i (UE) 2019/1937 i ustanowienia krajowych rozwiązań organizacyjnych i proceduralnych, w szczególności w zakresie wskazania właściwego organu, trybów prowadzenia postępowań oraz zasad finansowania kosztów nadzoru w granicach dopuszczonych prawem","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-27","document_date":"2026-02-27","change_date":"2026-09-07T12:38:20","closure_date":"2026-09-04","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["2363","2528","2529"]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:56:24+00:00');
INSERT INTO "bills" VALUES(10,'2580','Rządowy projekt ustawy o osobistych kontach inwestycyjnych','2026-08-27T11:16:56','2026-07-03',1,'skipped_prefilter','[]','{"term":10,"number":"2580","title":"Rządowy projekt ustawy o osobistych kontach inwestycyjnych","description":"projekt dotyczy wprowadzenia nowych, dobrowolnych i bezpłatnych narzędzi do oszczędzania oraz inwestowania ? Osobiste Konto Inwestycyjne (OKI). Rozwiązanie umożliwi inwestowanie w akcje, obligacje oraz inne instrumenty finansowe z pełnym zwolnieniem od podatku dochodowego do 100 tys. zł. Dla aktywów oszczędnościowych, takich jak lokaty czy obligacje oszczędnościowe, zwolnienie wyniesie do 25 tys. zł. Projekt stanowi realizację priorytetów rządu. Nowe przepisy zaczną obowiązywać od 2027 roku.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-08","document_date":"2026-05-08","change_date":"2026-08-27T11:16:56","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2649','Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym','2026-09-04T12:53:16','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2649","title":"Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym","description":"projekt dotyczy ujednolicenia przepisów w zakresie biernego prawa wyborczego (prawa wybieralności) w organach jednostek samorządu terytorialnego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-15","document_date":"2026-05-15","change_date":"2026-09-04T12:53:16","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2667','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.','2026-08-27T11:19:19','2026-07-17',1,'skipped_prefilter','[]','{"term":10,"number":"2667","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.","description":"projekt dotyczy uregulowania między Polską a Albanią wzajemnych stosunków w dziedzinie zabezpieczenia społecznego, w tym wprowadzenia możliwości korzystania przy ustalaniu prawa do świadczeń długoterminowych (emerytur i rent) z zasady sumowania okresów ubezpieczenia oraz możliwości transferu świadczeń nabytych na podstawie ustawodawstwa Polski, w przypadku przeniesienia swojego miejsca zamieszkania na terytorium Albanii i odwrotnie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:19:19","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2670','Senacki projekt ustawy o zmianie ustawy - Kodeks wyborczy oraz ustawy o referendum lokalnym','2026-09-04T12:42:45','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2670","title":"Senacki projekt ustawy o zmianie ustawy - Kodeks wyborczy oraz ustawy o referendum lokalnym","description":"projekt dotyczy wprowadzenia zmian w zasadach przeprowadzania głosowania i ustalania wyników wyborów, doprecyzowania kompetencji organów wyborczych oraz modyfikacji przepisów dotyczących organizacji i przebiegu referendów lokalnych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-22","document_date":"2026-05-21","change_date":"2026-09-04T12:42:45","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2677','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników','2026-09-04T12:51:49','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2677","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników","description":"projekt dotyczy wprowadzenia rozwiązań ograniczających część obowiązków administracyjnych dla przedsiębiorców, które ułatwią prowadzenie działalności m.in. poprzez likwidację wybranych obowiązków administracyjnych, tj.: (1) zniesienie obowiązku składania oddzielnej informacji o spisie z natury; (2) rezygnację z obowiązku wykazywania w JPK_VAT podstawy opodatkowania przy zakupach od podatników spoza terytorium Polski, towarów i usług objętych zwolnieniem z podatku; (3) likwidację obowiązku zapłaty VAT w ciągu 14 dni przy zakupie środka transportu z innego państwa UE; (4) ograniczenie naliczania odsetek od VAT przy imporcie w sytuacjach, gdy opóźnienie płatności jest niezależne od podatnika","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:51:49","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2693','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-09-03T10:13:34',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2693","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy zapewnienia skuteczniejszych narzędzi do reagowania na nielegalne treści","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-03T10:13:34","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2694','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-09-04T12:53:42','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2694","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy ustanowienia Prezesa Urzędu Komunikacji Elektronicznej głównym organem nadzorującym stosowanie nowych przepisów i pełniącym funkcję koordynatora ds. usług cyfrowych; wprowadzenia nowych mechanizmów rozpatrywania sporów, zgłoszeń nielegalnych treści oraz dostępu do danych dużych platform internetowych, w celach naukowych dotyczących m.in. dezinformacji czy bezpieczeństwa w sieci","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:53:42","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2698','Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw','2026-08-27T11:21:36','2026-07-31',1,'skipped_prefilter','[]','{"term":10,"number":"2698","title":"Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia nowej formy opieki - punkt opieki dziennej; wprowadzenia nowych uprawnień dla osób pracujących z najmłodszymi dziećmi (w tym m.in.: płatny czas na podnoszenie kwalifikacji zawodowych; 33-procentowa ulga na przejazdy publicznym transportem zbiorowym); nowe wymagania dotyczące plac zabaw przy żłobkach; propozycji ustanowienia 4 kwietnia Dniem Opiekuna Małego Dziecka","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:21:36","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2699','Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie','2026-08-27T11:18:01','2026-07-17',1,'analyzed','["cudzoziemcy", "nieruchomosci_cudzoziemcy"]','{"term":10,"number":"2699","title":"Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","description":"projekt dotyczy usprawnienia kontroli nabywania przez cudzoziemców nieruchomości w Polsce. Notariusze będą przesyłać dokumenty do Ministerstwa Spraw Wewnętrznych i Administracji wyłącznie w formie elektronicznej. Dzięki temu ich obieg stanie się szybszy, bezpieczniejszy i bardziej przejrzysty. Zmiany wpisują się w proces cyfryzacji administracji publicznej i poprawiają nadzór nad zakupem nieruchomości przez cudzoziemców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:18:01","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-06-09", "print_number": "2699", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-06-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-06-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SPC", "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-06-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "children": []}]}, {"stage_name": "I czytanie w komisjach", "stage_type": "Reading", "date": "2026-07-02", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Praca w komisjach po I czytaniu", "stage_type": "CommitteeWork", "date": "2026-07-02", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-07-02", "print_number": "2755", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/2755/2755.pdf", "text_after3": null, "children": []}]}, {"stage_name": "II czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-07-15", "print_number": null, "sitting_num": 62, "decision": "niezwłocznie przystąpiono do III czytania", "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "III czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-07-17", "print_number": null, "sitting_num": 62, "decision": "uchwalono", "committee_code": null, "report_file": null, "text_after3": "https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf", "children": [{"stage_name": "Głosowanie", "stage_type": "Voting", "date": "2026-07-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]}, {"stage_name": "Stanowisko Senatu", "stage_type": "SenatePosition", "date": "2026-07-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Ustawę przekazano Prezydentowi do podpisu", "stage_type": "ToPresident", "date": "2026-07-27", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Prezydent podpisał ustawę", "stage_type": "PresidentSignature", "date": "2026-08-13", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Uchwalono", "stage_type": "End", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]','e5f70fefbeb72530a78121526b37689046f2f6e79537583eaed383eac3fdadac','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Правительственный проект меняет способ передачи документов о покупке недвижимости (а также долей и акций компаний-владельцев недвижимости) иностранцами: нотариусы будут отправлять выписки в МВД (MSWiA) только в электронном виде через систему CREWAN, а не на бумаге. Сроки не меняются — нотариус по-прежнему обязан отправить документы в течение 7 дней с момента их составления. Правила самого приобретения недвижимости иностранцами (разрешения, освобождения) проект не затрагивает. Для сторон сделки предусмотрена новая небольшая плата за размещение документа в репозитории (в проекте подзаконного акта — 5 zł за документ), но при этом отпадает необходимость оплачивать дополнительную бумажную выписку (обычно 30–60 zł). Государство получает более быстрый и полный контроль за законностью приобретений недвижимости иностранцами.","key_changes":["Нотариус обязан размещать электронные выписки/копии/отписи документов в CREWAN в формате с возможностью поиска по тексту","Krajowa Rada Notarialna незамедлительно пересылает эти документы министру внутренних дел через телеинформационную систему","Введена плата, взимаемая нотариусом со сторон сделки за размещение документа в репозитории (в проекте распоряжения — 5 zł за документ)","Расширен перечень документов, хранимых в CREWAN (изменения в art. 92a Prawa o notariacie); требуется квалифицированная электронная подпись нотариуса","Проект распоряжения предусматривает срок хранения документов в репозитории — 5 лет с конца календарного года размещения","К документам, составленным до вступления закона в силу, применяются прежние правила"],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранцы, приобретающие доли/акции компаний — владельцев недвижимости","иностранцы-наследники недвижимости в Польше","нотариусы и Krajowa Rada Notarialna"],"practical_impact":"Для иностранца — покупателя или наследника недвижимости меняется только техническая сторона: нотариус не готовит бумажную выписку для МВД, а отправляет документ электронно, что снижает общие расходы на нотариальные действия, хотя добавляется отдельная небольшая плата за размещение в репозитории. Проверка законности сделки министерством станет быстрее.","effective_date":"Закон вступает в силу через 3 месяца со дня опубликования","confidence":0.85,"rationale":"Проект не меняет правил легализации пребывания или права на приобретение недвижимости, а лишь цифровизует передачу документов, что для иностранцев имеет косвенное значение (расходы, скорость контроля).","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v1","input_chars":80000,"truncated":true,"text_source":"pdf","created_at":"2026-09-07T13:53:37Z","input_tokens":40557,"output_tokens":1049,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2699/2699.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2700','Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw','2026-09-02T08:24:32','2026-07-31',1,'skipped_prefilter','[]','{"term":10,"number":"2700","title":"Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw","description":"projekt dotyczy poprawy dostępności transportu publicznego, szczególnie na obszarach wiejskich i w mniejszych miejscowościach oraz skuteczniejszego przeciwdziałania wykluczeniu transportowemu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T08:24:32","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2701','Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych','2026-08-27T11:20:22','2026-07-17',1,'skipped_prefilter','[]','{"term":10,"number":"2701","title":"Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych","description":"projekt dotyczy stworzenia odrębnej, szczególnej podstawy prawnej umożliwiającej PEFRON nieodpłatne przekazywanie osobom z niepełnosprawnościami oraz rodzinom, których członkami są osoby z niepełnosprawnościami, środków materialnych i niematerialnych pochodzących z rezerw strategicznych, udostępnionych Funduszowi w celu realizacji programów","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-28","document_date":"2026-05-27","change_date":"2026-08-27T11:20:22","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2737','Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw','2026-09-04T12:45:37','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2737","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia zasad funkcjonowania spółek z ograniczoną odpowiedzialnością oraz dostosowania je do obrotu cyfrowego. Zmiany mają ułatwić prowadzenie firm, w szczególności w sytuacjach, gdy wspólnicy kontaktują się zdalnie lub przebywają za granicą. Nowe przepisy ograniczają wymogi dotyczące papierowych dokumentów i podpisów, umożliwiając częstsze korzystanie z formy elektronicznej, np. e-maila lub skanu dokumentu. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-22","document_date":"2026-06-19","change_date":"2026-09-04T12:45:37","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2750','Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw','2026-09-04T10:16:54','2026-07-31',1,'skipped_prefilter','[]','{"term":10,"number":"2750","title":"Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"projekt dotyczy zmiany przepisów w zakresie obowiązku wniesienia albo uzupełnienia zaliczki na poczet opłaty za przyłączenie do sieci. Projekt nie ingeruje w konstrukcję zaliczki, lecz doprecyzowuje zakres podmiotowy i czasowy przepisów przejściowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-18","document_date":"2026-06-18","change_date":"2026-09-04T10:16:54","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2769','Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach','2026-09-04T12:41:40','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2769","title":"Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach","description":"projekt dotyczy ustanowienia przepisów służących stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2024/900 z dnia 13 marca 2024 r. W myśl projektu organem wiodącym, któremu powierzone zostaną zadania w zakresie ww. rozporządzenia  oraz nadzór nad jego stosowaniem będzie PKW, a pozostałymi organami będą: Prezes UKE, KRRiT, Prezes UKOiK oraz Prezes UODO. Postępowania będą się toczyć w trybie przewidzianym w kpa.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-26","document_date":"2026-06-25","change_date":"2026-09-04T12:41:40","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2778','Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-09-04T10:24:02','2026-07-31',1,'skipped_prefilter','[]','{"term":10,"number":"2778","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"projekt dotyczy wzmocnienia prawa obywateli do ochrony zdrowia i czystego powietrza. Mieszkańcy, przedsiębiorcy i organizacje społeczne będą mogli składać skargi - bez wykazania interesu prawnego - na programy ochrony powietrza, ich aktualizacje, plany działań krótkoterminowych, a także na bezczynność organów odpowiedzialnych za ich przyjęcie. Programy ochrony powietrza są tworzone wtedy, gdy w danym regionie przekroczone zostają normy jego jakości.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-03","change_date":"2026-09-04T10:24:02","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2799','Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta','2026-09-04T12:47:34','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2799","title":"Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta","description":"projekt dotyczy dostosowania polskich przepisów do prawa Unii Europejskiej, których celem jest wspieranie konsumentów w podejmowaniu bardziej świadomych decyzji zakupowych. Wprowadzone zmiany ułatwią rozpoznawanie rzetelnych informacji o produktach oraz ograniczą możliwość stosowania przez przedsiębiorców wprowadzających w błąd deklaracji dotyczących wpływu produktów na środowisko (tzw. ?greenwashingu?)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-09-04T12:47:34","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2801','Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji','2026-09-04T12:44:26','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2801","title":"Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji","description":"projekt dotyczy ułatwienia komunikacji między pracodawcą, zakładową organizacją związkową oraz radą pracowników. Zamiast obowiązkowego obiegu dokumentów w formie papierowej możliwe będzie korzystanie również z formy elektronicznej lub dokumentowej (np. PDF), o ile strony wyrażą na to zgodę. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-09-04T12:44:26","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2810','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.','2026-09-03T16:18:19',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2810","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.","description":"projekt dotyczy m.in. możliwości sumowania polskich oraz japońskich okresów ubezpieczenia, w celu przyznania prawa do świadczeń oraz możliwości dokonywania wypłaty\npolskich świadczeń osobom uprawnionym mającym miejsce zamieszkania na terytorium Japonii","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-13","document_date":"2026-07-13","change_date":"2026-09-03T16:18:19","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
