INSERT INTO "bills" VALUES(10,'2874','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o ustanowieniu Dnia Działacza Opozycji Antykomunistycznej i Osoby Represjonowanej z Powodów Politycznych','2026-09-01T19:39:29',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2874","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o ustanowieniu Dnia Działacza Opozycji Antykomunistycznej i Osoby Represjonowanej z Powodów Politycznych","description":"projekt dotyczy ustanowienia dnia 28 czerwca świętem państwowym - Dniem Działacza Opozycji Antykomunistycznej i Osoby Represjonowanej z Powodów Politycznych - upamiętniającym protesty robotnicze: Poznański Czerwiec (28-29.06.1956 r.), Radomski Czerwiec (25.06.1976 r.) jako punkty odniesienia dla kolejnych zrywów wolnościowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-29","document_date":"2026-06-28","change_date":"2026-09-01T19:39:29","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2883','Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym','2026-09-01T19:48:08',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2883","title":"Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym","description":"projekt dotyczy wyznaczenia stref wielofunkcyjnych z zabudową zagrodową bez konieczności uwzględniania posiadanych już rezerw terenów budowlanych w gminie; umożliwienia wydawania decyzji o warunkach zabudowy zagrodowej, czyli zabudowy powiązanej z prowadzonym gospodarstwem, również poza obszarami uzupełnienia zabudowy, pod warunkiem spełnienia ustawowych przesłanek dotyczących statutu rolnika, ładu przestrzennego, dostępu do drogi publicznej, uzbrojenia terenu oraz kontynuacji funkcji i parametrów zabudowy wynikających z analizy urbanistycznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-20","document_date":"2026-07-20","change_date":"2026-09-01T19:48:08","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2884','Poselski projekt ustawy o zmianie ustawy o znakach Sił Zbrojnych Rzeczypospolitej Polskiej','2026-09-01T19:49:38',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2884","title":"Poselski projekt ustawy o zmianie ustawy o znakach Sił Zbrojnych Rzeczypospolitej Polskiej","description":"projekt dotyczy zmiany zapisów dotyczących prawa posiadania sztandaru jednostki wojskowej. Nowelizacja zakłada, że prawo do posiadania sztandaru będzie przysługiwało jednostkom wojskowym Sił Zbrojnych Rzeczypospolitej Polskiej przeznaczonym do prowadzenia walki zbrojnej lub zabezpieczenia bojowego działań oraz szkołom wojskowym. Zgodnie z obowiązującym stanem prawnym prawo posiadania sztandaru przysługuje jednostkom liniowym wszystkich rodzajów sił zbrojnych oraz szkołom wojskowym. W rozumieniu zmienianej ustawy jednostką liniową jest samodzielna jednostka organizacyjna zdolna do prowadzenia walki zbrojnej lub zabezpieczenia bojowego działań.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-20","document_date":"2026-07-20","change_date":"2026-09-01T19:49:38","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2885','Poselski projekt ustawy o zmianie ustawy o działalności leczniczej i ustawy o finansach publicznych','2026-09-01T19:51:32',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2885","title":"Poselski projekt ustawy o zmianie ustawy o działalności leczniczej i ustawy o finansach publicznych","description":"projekt dotyczy objęcia obowiązkiem zamieszczania informacji w Centralnym Rejestrze Umów Jednostek Sektora Finansów Publicznych podmiotów leczniczych działających w formie spółek kapitałowych, w których wskazane podmioty publiczne, samodzielnie albo wspólnie, bezpośrednio lub pośrednio, dysponują większością głosów. Projekt nie obejmuje prywatnych podmiotów leczniczych wyłącznie z tego powodu, że zawarły umowę z Narodowym Funduszem Zdrowia. Projekt reguluje również zakładanie kont objętych nim podmiotów w systemie CRU.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-17","document_date":"2026-07-17","change_date":"2026-09-01T19:51:32","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2998','Rządowy projekt ustawy o zmianie ustawy o finansowym wspieraniu produkcji audiowizualnej oraz niektórych innych ustaw','2026-09-04T10:48:29',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2998","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wspieraniu produkcji audiowizualnej oraz niektórych innych ustaw","description":"projekt dotyczy: uproszczenia procedur i zwalczenia negatywnych zjawisk w dziedzinie produkcji audiowizualnej. Proponowane rozwiązania w szczególności polegają na wprowadzeniu: nowych okresów rozliczeniowych dla wniosków o wsparcie finansowe i nowego terminu na składanie takich wniosków, możliwości ustanawiania zabezpieczenia na środkach zdeponowanych na kontach powierniczych w bankach jako zachęty, zmian dotyczących raportowania przed podmioty prowadzące kina, a także zmian dotyczących przekazywania kopii filmu do Filmoteki Narodowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-09-04T10:48:29","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'2999','Rządowy projekt ustawy o zmianie ustawy o rybołówstwie morskim oraz ustawy o organizacji rynku rybnego','2026-09-04T13:51:35',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2999","title":"Rządowy projekt ustawy o zmianie ustawy o rybołówstwie morskim oraz ustawy o organizacji rynku rybnego","description":"projekt dotyczy umożliwienia stosowania w krajowym porządku prawnym zrewidowanych przepisów Unii Europejskiej w zakresie kontroli rybołówstwa; projekt reguluje raportowanie działalności połowowej, monitorowanie statków rybackich, zdalne monitorowanie elektroniczne, weryfikację mocy silników i pojemności statków, ważenie produktów rybołówstwa, rejestry naruszeń i kapitanów, system punktów za poważne naruszenia, rybołówstwo rekreacyjne, elektroniczny obieg dokumentów na rynku rybnym oraz sankcje pieniężne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-09-04T13:51:35","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'3002','Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne','2026-09-03T19:08:12',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3002","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne","description":"projekt dotyczy uchylenia obowiązującego od 2012 r. całkowitego zakazu reklamy aptek i punktów aptecznych; umożliwienia reklamowania usług świadczonych przez farmaceutów, takich jak: opieka farmaceutyczna, szczepienia, przeglądy lekowe czy podstawowe badania diagnostyczne; podwyższenia wysokości kary za prowadzenie reklamy niezgodnej z przepisami z 50 tys. zł do 100 tys. zł","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-05","document_date":"2026-08-05","change_date":"2026-09-03T19:08:12","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
