INSERT INTO "bills" VALUES(10,'3007','Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego "Czyste Powietrze"','2026-09-04T11:14:39',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3007","title":"Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego \"Czyste Powietrze\"","description":"projekt dotyczy pomocy osobom, które skorzystały z programu \"Czyste Powietrze\", ale z powodu np. nieuczciwych działań wykonawców nie zrealizowały prawidłowo inwestycji i muszą oddać otrzymane dofinansowanie. Nowe przepisy mają chronić poszkodowanych przed koniecznością zwrotu pieniędzy, jeżeli nieprawidłowości powstały bez ich winy. W określonych przypadkach będą oni mogli zawiesić spłatę, uzyskać ulgę, a nawet zostać zwolnieni z obowiązku zwrotu dofinansowania.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-13","document_date":"2026-08-13","change_date":"2026-09-04T11:14:39","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
