INSERT INTO "bills" VALUES(10,'3029','Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi','2026-09-01T19:15:28',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3029","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi","description":"projekt dotyczy wzmocnienia ochrony działalności rolniczej oraz ograniczenia konfliktów społecznych związanych m.in. z postępującą urbanizacją obszarów wiejskich. Rolnicy prowadzący działalność zgodnie z prawem zyskają większą pewność, że typowe uciążliwości związane z produkcją rolną, takie jak hałas, zapachy czy odgłosy zwierząt, nie będą podstawą do nieuzasadnionego ograniczania ich działalności. Projekt zakłada także lepsze informowanie osób kupujących nieruchomości na wsi o możliwych uciążliwościach związanych z działalnością rolniczą. Projekt realizuje priorytet polityki Rady Ministrów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-19","document_date":"2026-08-19","change_date":"2026-09-01T19:15:28","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
INSERT INTO "bills" VALUES(10,'3030','Rządowy projekt ustawy o usprawnieniu procesu inwestycyjnego w zakresie kluczowych inwestycji infrastrukturalnych','2026-09-04T15:09:44',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3030","title":"Rządowy projekt ustawy o usprawnieniu procesu inwestycyjnego w zakresie kluczowych inwestycji infrastrukturalnych","description":"projekt dotyczy przyspieszenia przygotowania i budowy najważniejszych inwestycji infrastrukturalnych, które mają znaczenie dla obronności Polski, bezpieczeństwa energetycznego, ochrony przeciwpowodziowej oraz rozwoju gospodarczego. Dla wybranych inwestycji zostaną wprowadzone prostsze procedury administracyjne, krótsze terminy oraz pierwszeństwo w rozpatrywaniu spraw przez urzędy. Projekt obejmuje zamknięty katalog konkretnych inwestycji m.in. \"Droga Czerwona\" w Gdyni zapewniająca dostęp do terminala w porcie, rozbudowa portów w Gdyni i Świnoujściu, inwestycje na lotniskach w Rzeszowie, Krakowie i Warszawie, a także rozbudowa ważnych połączeń kolejowych. Uproszczone procedury obejmą także inwestycje potrzebne do realizacji infrastruktury towarzyszącej elektrowni jądrowej na Pomorzu. Dotyczy to m.in. dróg, kolei i infrastruktury hydrotechnicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-20","document_date":"2026-08-19","change_date":"2026-09-04T15:09:44","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00');
